API Rate Limiting with Redis: Token Bucket, Sliding Window, and Per-Client Limits
Your API has no rate limiting. A single client sends 10,000 requests per second. Your database melts. Here is how to protect your services.
Token Bucket with Redis
import Redis from "ioredis";
const RATE_LIMIT_SCRIPT = `
local key = KEYS[1]
local limit = tonumber(ARGV[1])
local window = tonumber(ARGV[2])
local now = tonumber(ARGV[3])
redis.call("ZREMRANGEBYSCORE", key, 0, now - window)
local count = redis.call("ZCARD", key)
if count >= limit then return 0 end
redis.call("ZADD", key, now, now .. math.random())
redis.call("EXPIRE", key, window / 1000)
return 1
`;
async function checkRateLimit(redis: Redis, clientId: string, limit: number, windowMs: number): Promise<boolean> {
const key = `rate:${clientId}`;
const allowed = await redis.eval(RATE_LIMIT_SCRIPT, 1, key, limit, windowMs, Date.now());
return allowed === 1;
}
Express Middleware
function rateLimiter(limit = 100, windowMs = 60000) {
return async (req: Request, res: Response, next: NextFunction) => {
const clientId = req.ip;
const allowed = await checkRateLimit(redis, clientId, limit, windowMs);
if (\!allowed) {
res.set("Retry-After", String(Math.ceil(windowMs / 1000)));
return res.status(429).json({ error: "Too many requests" });
}
next();
};
}
// Different limits per route
app.use("/api/auth", rateLimiter(10, 60000)); // 10/min for auth
app.use("/api/search", rateLimiter(30, 60000)); // 30/min for search
app.use("/api", rateLimiter(100, 60000)); // 100/min default
Response Headers
Always include rate limit headers so clients can self-throttle:
- X-RateLimit-Limit: Max requests allowed
- X-RateLimit-Remaining: Requests left in current window
- X-RateLimit-Reset: Unix timestamp when window resets
- Retry-After: Seconds to wait (on 429 responses)
